import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import Ajv from "ajv";
import standaloneCode from "ajv/dist/standalone/index.js";

const schema = JSON.parse(
  await readFile(new URL("../src/schemas/flowsensa-tooling-requirement.schema.json", import.meta.url), "utf8"),
);
const ajv = new Ajv({ allErrors: true, strict: true, code: { source: true, esm: true } });
ajv.addSchema(schema);

const generated = standaloneCode(ajv, { validateFlowsensaImport: schema.$id });
const banner =
  "/* oxlint-disable */\n// @ts-nocheck\n// Generated by scripts/generate-validators.mjs. Do not edit by hand.\n";
const outputUrl = new URL("../src/generated/validators.ts", import.meta.url);
await writeFile(outputUrl, `${banner}${generated}\n`, "utf8");
console.log(`Generated ${fileURLToPath(outputUrl)}`);
